      "intro": "Safe small-talk lines: weather, greetings, compliments, and easy goodbyes.",
      "introZh": "商务寒暄：天气、问候、赞美、从容道别。",
      "cards": [
        { "id": "elite_smalltalk_01", "title": "196. 今天天气不错。| Weather", "audioKey": "196", "sentence": "今天天气不错，适合出来走走。", "pinyin": "Jīntiān tiānqì búcuò, shìhé chūlái zǒu zou.", "translation": "The weather is nice today—good for a walk.", "undercurrent": { "origin": "寒暄经典。安全话题。", "context": "见面暖场。", "signal": "轻松。" }, "vocabList": [] },
        { "id": "elite_smalltalk_02", "title": "197. 最近在忙什么？| How's it going", "audioKey": "197", "sentence": "最近在忙些什么？", "pinyin": "Zuìjìn zài máng xiē shénme?", "translation": "What have you been busy with lately?", "undercurrent": { "origin": "寒暄常用。", "context": "见到熟人。", "signal": "关心。" }, "vocabList": [] },
        { "id": "elite_smalltalk_03", "title": "198. 您气色真好。| Compliment", "audioKey": "198", "sentence": "您气色真好，最近一定有什么喜事。", "pinyin": "Nín qìsè zhēn hǎo, zuìjìn yídìng yǒu shénme xǐshì.", "translation": "You look great—something good must have happened recently.", "undercurrent": { "origin": "喜事= happy event。", "context": "赞美客户。", "signal": "赞美。" }, "vocabList": [{"word": "气色", "pinyin": "qì sè", "translation": "complexion / demeanor", "hskLevel": "7-9"}, {"word": "喜事", "pinyin": "xǐ shì", "translation": "good news", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_04", "title": "199. 哪里哪里，过奖了。| Modest", "audioKey": "199", "sentence": "哪里哪里，您过奖了。", "pinyin": "Nǎlǐ nǎlǐ, nín guòjiǎng le.", "translation": "Not at all—you flatter me.", "undercurrent": { "origin": "客套回应：哪里哪里。", "context": "被表扬时。", "signal": "谦虚。" }, "vocabList": [{"word": "过奖", "pinyin": "guò jiǎng", "translation": "to overpraise", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_05", "title": "200. 托您的福。| Grateful", "audioKey": "200", "sentence": "托您的福，一切都好。", "pinyin": "Tuō nín de fú, yíqiè dōu hǎo.", "translation": "Thanks to you, everything is fine.", "undercurrent": { "origin": "托您的福= thanks to your blessing。", "context": "回答近况。", "signal": "感恩。" }, "vocabList": [{"word": "托您的福", "pinyin": "tuō nín de fú", "translation": "thanks to your good fortune", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_06", "title": "201. 您先请。| After you", "audioKey": "201", "sentence": "您先请，您先请。", "pinyin": "Nín xiān qǐng, nín xiān qǐng.", "translation": "After you, please.", "undercurrent": { "origin": "礼让。", "context": "进门、入座、乘电梯。", "signal": "尊重。" }, "vocabList": [] },
        { "id": "elite_smalltalk_07", "title": "202. 咱们坐下慢慢聊。| No rush", "audioKey": "202", "sentence": "咱们坐下慢慢聊。", "pinyin": "Zánmen zuò xià mànman liáo.", "translation": "Let's sit down and chat slowly.", "undercurrent": { "origin": "慢慢聊= no rush。", "context": "会客。", "signal": "从容。" }, "vocabList": [] },
        { "id": "elite_smalltalk_08", "title": "203. 喝茶还是咖啡？| Hosting", "audioKey": "203", "sentence": "喝茶还是咖啡？", "pinyin": "Hē chá háishì kāfēi?", "translation": "Tea or coffee?", "undercurrent": { "origin": "招待选择。", "context": "客人落座。", "signal": "周到。" }, "vocabList": [{"word": "喝茶", "pinyin": "hē chá", "translation": "to have tea", "hskLevel": "7-9"}, {"word": "咖啡", "pinyin": "kā fēi", "translation": "coffee", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_09", "title": "204. 每次来都带东西。| Kind client", "audioKey": "204", "sentence": "您太客气了，每次来都带东西。", "pinyin": "Nín tài kèqi le, měi cì lái dōu dài dōngxi.", "translation": "You're too kind—you bring something every time.", "undercurrent": { "origin": "客套。", "context": "客户带礼物。", "signal": "不好意思。" }, "vocabList": [{"word": "客气", "pinyin": "kè qì", "translation": "to be polite / ceremonious", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_10", "title": "205. 应该的，应该的。| My duty", "audioKey": "205", "sentence": "应该的，应该的。", "pinyin": "Yīnggāi de, yīnggāi de.", "translation": "It's what I should do.", "undercurrent": { "origin": "客套回应。", "context": "对方感谢时。", "signal": "谦虚。" }, "vocabList": [] },
        { "id": "elite_smalltalk_11", "title": "206. 您先忙，不打扰了。| Considerate", "audioKey": "206", "sentence": "您先忙，我不打扰了。", "pinyin": "Nín xiān máng, wǒ bù dǎrǎo le.", "translation": "You go ahead—I won't disturb you.", "undercurrent": { "origin": "告辞。", "context": "看到对方忙。", "signal": "体贴。" }, "vocabList": [{"word": "打扰", "pinyin": "dǎ rǎo", "translation": "to disturb", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_12", "title": "207. 随时联系我。| Available", "audioKey": "207", "sentence": "有什么事随时联系我。", "pinyin": "Yǒu shénme shì suíshí liánxì wǒ.", "translation": "Contact me anytime if anything comes up.", "undercurrent": { "origin": "随时联系。", "context": "告别。", "signal": "可靠。" }, "vocabList": [{"word": "随时", "pinyin": "suí shí", "translation": "anytime", "hskLevel": "7-9"}, {"word": "联系", "pinyin": "lián xì", "translation": "to contact", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_13", "title": "208. 加个微信吧。| Connect", "audioKey": "208", "sentence": "咱们加个微信吧，方便沟通。", "pinyin": "Zánmen jiā ge Wēixìn ba, fāngbiàn gōutōng.", "translation": "Let's add each other on WeChat for easier communication.", "undercurrent": { "origin": "2026年标准动作。", "context": "初次见面后。", "signal": "建立联系。" }, "vocabList": [{"word": "加个微信", "pinyin": "jiā gè wēi xìn", "translation": "to add on WeChat", "hskLevel": "7-9"}, {"word": "沟通", "pinyin": "gōu tōng", "translation": "communication", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_14", "title": "209. 常来常往。| Keep in touch", "audioKey": "209", "sentence": "以后常来常往。", "pinyin": "Yǐhòu cháng lái cháng wǎng.", "translation": "Let's keep in touch regularly.", "undercurrent": { "origin": "常来常往= frequent contact。", "context": "告别。", "signal": "关系长久。" }, "vocabList": [{"word": "常来常往", "pinyin": "cháng lái cháng wǎng", "translation": "to visit each other often", "hskLevel": "7-9"}] },
        { "id": "elite_smalltalk_15", "title": "210. 您慢走。| Take care", "audioKey": "210", "sentence": "那我就不远送了，您慢走。", "pinyin": "Nà wǒ jiù bù yuǎn sòng le, nín màn zǒu.", "translation": "Then I won't see you off further. Take care.", "undercurrent": { "origin": "慢走= take care。", "context": "送客到门口。", "signal": "礼貌。" }, "vocabList": [{"word": "远送", "pinyin": "yuǎn sòng", "translation": "to see someone off far", "hskLevel": "7-9"}, {"word": "慢走", "pinyin": "màn zǒu", "translation": "take care (said when seeing off)", "hskLevel": "7-9"}] }
      ]
